"""Calcula el factorial de un número utilizando recursión y incluye tests unitarios."""

from typing import Optional
import sys
import unittest


def factorial(n: int) -> int:
    """Calcula el factorial de un número entero positivo utilizando recursión.

    Args:
        n: Número entero positivo para calcular su factorial.

    Returns:
        El factorial del número.

    Raises:
        TypeError: Si el input no es un entero.
        ValueError: Si el número es negativo.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1
    return n * factorial(n - 1)


